pub(super) fn seal(
    store: &ArtifactStore,
    scope: RankingsScope,
    source_snapshot: EvidenceDigest,
    catalog_outcome: FetchOutcome,
    catalog_ref: Option<EvidenceDigest>,
    plan_ref: Option<EvidenceDigest>,
    events: Vec<EventProgress>,
    absent_families: Vec<String>,
    collection: EvidenceDigest,
) -> anyhow::Result<EvidenceDigest> {
    if events.is_empty() || events.iter().any(|event| !event.terminal || event.head_checkpoint.is_none()) {
        bail!("cannot seal an incomplete ranking collection");
    }
    let snapshot = CollectionFinalSnapshot {
        collection, source_snapshot, scope,
        catalog_outcome,
        catalog_ref, plan_ref,
        event_heads: events.iter().map(|event| EventHeadRef {
            event_short: event.event_short.clone(), head_checkpoint: event.head_checkpoint.clone(),
            page_count: event.page_count, terminal: event.terminal,
        }).collect(),
        coverage: CoverageSummary { total_requested: events.len() as u64,
            completed: events.len() as u64, absent_families },
        unique_athletes: store.ranking_collection_stats(&collection)?.unique_athletes,
    };
    let digest = put(store, &snapshot)?;
    store.seal_rankings(&collection, &digest)?;
    Ok(digest)
}
