pub(super) fn catalog(
    store: &ArtifactStore, scope: &RankingsScope, collection: EvidenceDigest, outcome: &FetchOutcome,
) -> anyhow::Result<CatalogPublication> {
    let receipt = receipt(outcome)?;
    let capture = receipt.rankings.as_ref().context("catalog capture metadata missing")?;
    if capture.capture != RankingsCapture::Navigation { bail!("wrong catalog capture kind"); }
    let catalog = EventCatalog::from_nav(&raw(store, receipt)?, &scope.requested_families)?;
    if catalog.list_id != scope.list_id || catalog.season_id != scope.season {
        bail!("catalog list or season differs from requested scope");
    }
    let absent = catalog.absent_families.into_iter().map(|family| family.family).collect();
    let catalog_digest = put(store, &catalog)?;
    let plan = catalog.into_plan(collection, scope.projection_grade)?;
    let events = plan.events.iter().map(|event| EventProgress {
        event_short: event.short.clone(), event_id: event.event_id, is_relay: event.is_relay,
        next_page: 1, head_checkpoint: None, page_count: 0, terminal: false,
    }).collect();
    Ok(CatalogPublication { catalog: catalog_digest, plan: put(store, &plan)?, events, absent })
}
